<div id="event-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-slate-900/50 p-4" role="dialog" aria-modal="true"><div class="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div class="flex items-start justify-between"><div><h2 id="form-title" class="text-lg font-semibold">เพิ่มกำหนดการ</h2><p class="mt-1 text-sm text-gray-500">เพิ่มคลาสโรงเรียนบาสและกำหนดโค้ชผู้สอน</p></div><button class="close-modal text-xl text-gray-400">×</button></div><form id="event-form" class="mt-5 space-y-4"><input id="event-id" type="hidden"><div><label class="mb-1 block text-sm font-medium">ชื่อกำหนดการ</label><input id="title" required class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"></div><div><label class="mb-1 block text-sm font-medium">รายละเอียด</label><textarea id="description" rows="2" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"></textarea></div><label class="flex items-center gap-2 text-sm"><input id="all-day" type="checkbox"> ทั้งวัน</label><div class="grid gap-3 sm:grid-cols-2"><div><label class="mb-1 block text-sm font-medium">เริ่ม</label><input id="starts-at" required type="datetime-local" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"></div><div><label class="mb-1 block text-sm font-medium">สิ้นสุด</label><input id="ends-at" type="datetime-local" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"></div></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="mb-1 block text-sm font-medium">ทำซ้ำ</label><select id="recurrence" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"><option value="none">ไม่ทำซ้ำ</option><option value="daily">ทุกวัน</option><option value="weekly">ทุกสัปดาห์</option><option value="monthly">ทุกเดือน</option></select></div><div><label class="mb-1 block text-sm font-medium">สิ้นสุดการทำซ้ำ</label><input id="recurrence-until" type="date" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"></div></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="mb-1 block text-sm font-medium">สี</label><input id="color" type="color" value="#2563eb" class="h-10 w-full rounded-lg border border-gray-300 p-1"></div><div><label class="mb-1 block text-sm font-medium">โค้ชผู้สอน</label><select id="coach" required class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"><option value="">เลือกโค้ช</option>@foreach($coaches as $coach)<option value="{{ $coach->id }}">{{ $coach->us_name }}</option>@endforeach</select></div></div><div><label class="mb-1 block text-sm font-medium">รายชื่อนักเรียน (คั่นด้วยจุลภาค)</label><input id="students" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm" placeholder="น้องพีท, น้องมินท์"></div><div class="flex justify-between pt-2"><button id="delete-event" type="button" class="hidden rounded-lg px-4 py-2.5 text-sm font-medium text-red-600 hover:bg-red-50">ลบกำหนดการ</button><div class="ml-auto flex gap-2"><button type="button" class="close-modal rounded-lg px-4 py-2.5 text-sm font-medium text-gray-600 hover:bg-gray-100">ยกเลิก</button><button type="submit" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-medium text-white hover:bg-blue-700">บันทึก</button></div></div></form></div></div>

<div id="details-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-slate-900/50 p-4" role="dialog" aria-modal="true"><div class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><div class="flex items-start justify-between gap-4"><div class="flex items-start gap-3"><span id="detail-color" class="mt-1 h-4 w-4 rounded-full"></span><div><h2 id="detail-title" class="text-xl font-semibold"></h2><p id="detail-time" class="mt-1 text-sm text-gray-500"></p></div></div><button class="close-details text-xl text-gray-400">×</button></div><div class="mt-6 grid gap-4 rounded-xl bg-slate-50 p-4 sm:grid-cols-2"><div><p class="text-xs font-medium uppercase tracking-wide text-gray-500">โค้ชผู้สอน</p><p id="detail-coach" class="mt-1 font-medium"></p></div><div><p class="text-xs font-medium uppercase tracking-wide text-gray-500">จำนวนนักเรียน</p><p id="detail-count" class="mt-1 font-medium"></p></div></div><div class="mt-5"><p class="text-xs font-medium uppercase tracking-wide text-gray-500">รายชื่อนักเรียน</p><div id="detail-students" class="mt-2 flex flex-wrap gap-2"></div></div><div class="mt-5"><p class="text-xs font-medium uppercase tracking-wide text-gray-500">รายละเอียด</p><p id="detail-description" class="mt-2 whitespace-pre-line text-sm leading-6 text-gray-600"></p></div><div class="mt-6 flex justify-end"><button id="edit-event" class="hidden rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-medium text-white">แก้ไขกำหนดการ</button></div></div></div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    const csrf = '{{ csrf_token() }}', api = '{{ route('admin.courses.calendar.events') }}', courseEventApi = '{{ url('/admin/courses/calendar/course-events') }}';
    const el = document.getElementById('course-calendar'), filter = document.getElementById('coach-filter'), formModal = document.getElementById('event-modal'), detailsModal = document.getElementById('details-modal'), form = document.getElementById('event-form'); let activeEvent = null, editingCourseEvent = null, calendar;
    const courtSections = @json($courtSections);
    // ไม่ใช้ช่องรายละเอียดข้อความแล้ว: ข้อมูลสำคัญจะแยกเป็น package และสนามแทน
    document.getElementById('description').parentElement.classList.add('hidden');
    const assignmentFields = document.createElement('div');
    assignmentFields.className = 'grid gap-3 sm:grid-cols-2';
    assignmentFields.innerHTML = `<div><label class="mb-1 block text-sm font-medium">ประเภทแพ็กเกจ</label><select id="event-package-type" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"><option value="">ไม่ระบุ</option><option value="group">เรียนรวม</option><option value="private">Private / ส่วนตัว</option></select></div><div><label class="mb-1 block text-sm font-medium">สนามที่ใช้เรียน</label><select id="event-court-section" class="w-full rounded-lg border border-gray-300 px-3 py-2.5 text-sm"><option value="">ยังไม่ระบุสนาม</option>${courtSections.map(section => `<option value="${section.id}">${escapeHtml(section.label)}</option>`).join('')}</select></div>`;
    form.querySelector('.flex.justify-between').before(assignmentFields);
    document.getElementById('detail-description').parentElement.classList.add('hidden');
    const detailGrid = detailsModal.querySelector('.mt-6.grid');
    detailGrid.insertAdjacentHTML('beforeend', '<div><p class="text-xs font-medium uppercase tracking-wide text-gray-500">ประเภทแพ็กเกจ</p><p id="detail-package-type" class="mt-1 font-medium"></p></div><div><p class="text-xs font-medium uppercase tracking-wide text-gray-500">สนามที่ใช้เรียน</p><p id="detail-court" class="mt-1 font-medium"></p></div>');
    const pad = n => String(n).padStart(2, '0'); const localInput = date => date ? `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}` : '';
    calendar = new FullCalendar.Calendar(el, { initialView: 'timeGridWeek', locale: 'th', firstDay: 1, height: 'auto', nowIndicator: true, selectable: true, editable: true, allDaySlot: true, slotMinTime: '08:00:00', slotMaxTime: '21:00:00', slotDuration: '00:30:00', headerToolbar: { left: 'prev,next today', center: 'title', right: 'dayGridMonth,timeGridWeek,timeGridDay,listWeek' }, buttonText: { today: 'วันนี้', month: 'เดือน', week: 'สัปดาห์', day: 'วัน', list: 'รายการ' },
        events: { url: api, extraParams: () => ({ coach: filter.value }) },
        eventDataTransform: event => filter.value === 'all' || String(event.extendedProps.coachId || '') === filter.value ? event : false,
        select: info => openForm(null, info.start, info.end, info.allDay), eventClick: info => { activeEvent = info.event; showDetails(info.event); }, eventDrop: persistMove, eventResize: persistMove, eventsSet: updateSummary });
    calendar.render(); filter.addEventListener('change', () => calendar.refetchEvents()); document.getElementById('new-event-button').addEventListener('click', () => { const start = new Date(calendar.getDate()); start.setHours(9, 0, 0, 0); const end = new Date(start); end.setHours(10); openForm(null, start, end, false); });
    document.querySelectorAll('.close-modal').forEach(btn => btn.addEventListener('click', closeForm));
    document.querySelectorAll('.close-details').forEach(btn => btn.addEventListener('click', closeDetails));
    formModal.addEventListener('click', e => { if (e.target === formModal) closeForm(); });
    detailsModal.addEventListener('click', e => { if (e.target === detailsModal) closeDetails(); });
    document.getElementById('edit-event').addEventListener('click', () => { closeDetails(); openForm(activeEvent); });
    form.addEventListener('submit', async event => {
        if (!editingCourseEvent) return;
        event.preventDefault(); event.stopImmediatePropagation();
        const source = editingCourseEvent.extendedProps;
        const data = { title: document.getElementById('title').value, starts_at: document.getElementById('starts-at').value, ends_at: document.getElementById('ends-at').value, package_type: document.getElementById('event-package-type').value || null, court_section_id: document.getElementById('event-court-section').value || null };
        const response = await fetch(`${courseEventApi}/${source.sourceScheduleId}/${source.occurrenceDate}`, { method: 'PUT', headers: {'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf}, body: JSON.stringify(data) });
        if (!response.ok) return alert('บันทึกการแก้ไขคอร์สไม่สำเร็จ');
        closeForm(); calendar.refetchEvents();
    }, true);
    function openForm(event = null, start = null, end = null, allDay = false) { document.getElementById('form-title').textContent = event ? 'แก้ไขกำหนดการ' : 'เพิ่มคลาสโรงเรียนบาส'; document.getElementById('event-id').value = event?.extendedProps.eventId || ''; document.getElementById('title').value = event?.title || 'คลาสโรงเรียนบาส'; document.getElementById('description').value = event?.extendedProps.description || ''; document.getElementById('all-day').checked = event?.allDay || allDay; document.getElementById('starts-at').value = localInput(event?.start || start); document.getElementById('ends-at').value = localInput(event?.end || end); document.getElementById('color').value = event?.backgroundColor || '#2563eb'; document.getElementById('coach').value = event?.extendedProps.coachId || ''; document.getElementById('students').value = (event?.extendedProps.students || []).join(', '); document.getElementById('recurrence').value = event?.extendedProps.recurrence || 'none'; document.getElementById('recurrence-until').value = event?.extendedProps.recurrenceUntil || ''; document.getElementById('delete-event').classList.toggle('hidden', !event); formModal.classList.remove('hidden'); formModal.classList.add('flex'); }
    function closeForm() { formModal.classList.add('hidden'); formModal.classList.remove('flex'); form.reset(); }
    function closeDetails() { detailsModal.classList.add('hidden'); detailsModal.classList.remove('flex'); }
    form.addEventListener('submit', async e => { e.preventDefault(); const id = document.getElementById('event-id').value, students = document.getElementById('students').value.split(',').map(s => s.trim()).filter(Boolean); const data = { title: document.getElementById('title').value, description: document.getElementById('description').value || null, starts_at: document.getElementById('starts-at').value, ends_at: document.getElementById('ends-at').value || null, all_day: document.getElementById('all-day').checked, color: document.getElementById('color').value, recurrence: document.getElementById('recurrence').value, recurrence_until: document.getElementById('recurrence-until').value || null, event_type: 'school_class', coach_id: document.getElementById('coach').value || null, coach_name: null, package_type: document.getElementById('event-package-type').value || null, court_section_id: document.getElementById('event-court-section').value || null, student_names: students }; const response = await fetch(id ? `${api}/${id}` : api, { method: id ? 'PUT' : 'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf}, body:JSON.stringify(data) }); if (!response.ok) { const result = await response.json().catch(() => ({})); return Swal.fire({icon:'error', title:'บันทึกไม่สำเร็จ', text:Object.values(result.errors || {}).flat()[0] || 'กรุณาตรวจสอบข้อมูล'}); } closeForm(); calendar.refetchEvents(); Toast.fire({icon:'success', title:id ? 'แก้ไขกำหนดการแล้ว' : 'เพิ่มคลาสโรงเรียนบาสแล้ว'}); });
    document.getElementById('delete-event').addEventListener('click', async () => { const id = document.getElementById('event-id').value; if (!id) return; const confirmation = await Swal.fire({icon:'warning', title:'ลบกำหนดการนี้?', text:'หากเป็นกำหนดการที่เกิดซ้ำ ระบบจะลบทั้งชุด', showCancelButton:true, confirmButtonText:'ลบกำหนดการ', cancelButtonText:'ยกเลิก', confirmButtonColor:'#dc2626'}); if (!confirmation.isConfirmed) return; const response = await fetch(`${api}/${id}`, {method:'DELETE',headers:{'X-CSRF-TOKEN':csrf}}); if (!response.ok) return Swal.fire({icon:'error',title:'ลบกำหนดการไม่สำเร็จ'}); closeForm(); calendar.refetchEvents(); Toast.fire({icon:'success',title:'ลบกำหนดการแล้ว'}); });
    async function persistMove(info) { if (info.event.extendedProps.kind !== 'personal') { info.revert(); return; } const p = info.event.extendedProps; const data = {title:info.event.title, description:p.description || null, starts_at:info.event.start.toISOString(), ends_at:info.event.end?.toISOString() || null, all_day:info.event.allDay, color:info.event.backgroundColor, recurrence:p.recurrence || 'none', recurrence_until:p.recurrenceUntil || null, event_type:p.eventType || 'school_class', coach_id:p.coachId || null, coach_name:null, package_type:p.packageTypeValue || null, court_section_id:p.courtSectionId || null, student_names:p.students || []}; const response = await fetch(`${api}/${p.eventId}`, {method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(data)}); if(!response.ok) { info.revert(); return Swal.fire({icon:'error',title:'เปลี่ยนเวลาไม่สำเร็จ'}); } calendar.refetchEvents(); Toast.fire({icon:'success',title:'อัปเดตเวลาแล้ว'}); }
    function showDetails(event) { const p = event.extendedProps, students = p.students || []; document.getElementById('detail-color').style.backgroundColor = event.backgroundColor; document.getElementById('detail-title').textContent = event.title; document.getElementById('detail-time').textContent = formatRange(event.start, event.end, event.allDay); document.getElementById('detail-coach').textContent = p.coach || 'ไม่ระบุ'; document.getElementById('detail-count').textContent = p.capacity || `${students.length} คน`; document.getElementById('detail-description').textContent = [p.description, p.packageType ? 'ประเภทแพ็กเกจ: ' + p.packageType : '', p.court ? 'สนามที่ใช้: ' + p.court : ''].filter(Boolean).join(' · ') || 'ไม่มีรายละเอียดเพิ่มเติม'; document.getElementById('detail-students').innerHTML = students.length ? students.map(s => `<span class="rounded-full bg-blue-50 px-3 py-1 text-sm text-blue-700">${escapeHtml(s)}</span>`).join('') : '<span class="text-sm text-gray-500">ยังไม่มีรายชื่อ</span>'; document.getElementById('edit-event').classList.toggle('hidden', p.kind !== 'personal' && p.kind !== 'course'); detailsModal.classList.remove('hidden'); detailsModal.classList.add('flex'); }
    function formatRange(start,end,allDay) { if(allDay) return start.toLocaleDateString('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'}) + ' · ทั้งวัน'; const d={weekday:'long',day:'numeric',month:'short',year:'numeric'}, t={hour:'2-digit',minute:'2-digit'}; return `${start.toLocaleDateString('th-TH',d)} · ${start.toLocaleTimeString('th-TH',t)}${end ? ' – '+end.toLocaleTimeString('th-TH',t):''}`; }
    function updateSummary(events) { document.getElementById('total-events').textContent=events.length; document.getElementById('total-coaches').textContent=new Set(events.map(e=>e.extendedProps.coach).filter(Boolean)).size; document.getElementById('total-hours').textContent=events.reduce((s,e)=>s+(e.end?Math.max(0,(e.end-e.start)/3600000):0),0).toFixed(1); }
    const baseOpenForm = openForm;
    openForm = function(event = null, start = null, end = null, allDay = false) {
        baseOpenForm(event, start, end, allDay);
        editingCourseEvent = event?.extendedProps.kind === 'course' ? event : null;
        document.getElementById('event-package-type').value = event?.extendedProps.packageTypeValue || '';
        document.getElementById('event-court-section').value = event?.extendedProps.courtSectionId || '';
    };
    const baseShowDetails = showDetails;
    showDetails = function(event) {
        baseShowDetails(event);
        document.getElementById('detail-package-type').textContent = event.extendedProps.packageType || 'ยังไม่ระบุประเภทแพ็กเกจ';
        document.getElementById('detail-court').textContent = event.extendedProps.court || 'ยังไม่ระบุสนาม';
    };
    function escapeHtml(s) { const d=document.createElement('div'); d.textContent=s; return d.innerHTML; }
});
</script>
@endsection
